#include <cstddef>

struct GrowthStats {
    std::size_t reallocations = 0;    // how many push_backs had to grow the buffer
    std::size_t elements_copied = 0;  // elements copied from an old buffer into a
                                      // new one, added up over all reallocations
    std::size_t final_capacity = 0;   // capacity() after the last push_back
};

GrowthStats measure_growth(double factor, std::size_t n);   // see growth_experiment.cpp

